import { useMemo } from 'react';

import {
  filterCommercialSelectOptions,
  isCommercialResultsFilterPage,
  resolveCommercialDrawerSelectValue,
} from 'components/Filter/utils/commercialSelectOptions';
import { Option } from 'models/Filters';

export type UseCommercialSelectOptionsParams = {
  pageName: string;
  rawOptions: Option[];
  formValue: unknown;
  defaultValue?: unknown;
};

export type UseCommercialSelectOptionsResult = {
  rawOptions: Option[];
  selectableOptions: Option[];
  isCommercialPage: boolean;
  commercialDisplayValue: string | null;
};

/**
 * Commercial Results drawer/quick-filter selects: baseline rows stay in
 * `rawOptions` (clear/sentinel) but are removed from `selectableOptions`;
 * `commercialDisplayValue` is null when the form is at baseline (placeholder).
 */
export function useCommercialSelectOptions({
  pageName,
  rawOptions,
  formValue,
  defaultValue,
}: UseCommercialSelectOptionsParams): UseCommercialSelectOptionsResult {
  const selectableOptions = useMemo(
    () => filterCommercialSelectOptions(pageName, rawOptions),
    [pageName, rawOptions],
  );

  const isCommercialPage = isCommercialResultsFilterPage(pageName);

  const commercialDisplayValue = useMemo(() => {
    if (!isCommercialPage) {
      return null;
    }
    return resolveCommercialDrawerSelectValue(
      pageName,
      formValue,
      defaultValue,
      selectableOptions,
    );
  }, [isCommercialPage, pageName, formValue, defaultValue, selectableOptions]);

  return {
    rawOptions,
    selectableOptions,
    isCommercialPage,
    commercialDisplayValue,
  };
}
